// Open reads all prologue and layout words bytewise before the final base
// alignment check. Every refusal names the first failed clause in SPEC §19.2.
func (block *RawTokensBlock) Open(base unsafe.Pointer, bytes int64) error {
	*block = RawTokensBlock{}
	if base == nil {
		return TableRefuseUnalignedBase
	}
	if bytes < 120 {
		return TableRefuseTruncated
	}
	header := unsafe.Slice((*byte)(base), 120)
	magic := binary.NativeEndian.Uint64(header)
	if magic != TableBlockMagic {
		if magic == 0x5343484d41424c4b {
			return TableRefuseForeignOrder
		}
		return TableRefuseNotACook
	}
	if binary.NativeEndian.Uint64(header[16:]) != TableBlockByteOrder {
		return TableRefuseNotACook
	}
	if binary.NativeEndian.Uint64(header[8:]) != BuildVersion {
		return TableRefuseWrongBuildVersion
	}
	used := int64(120)
	padding := (64 - (used % 64)) % 64
	if padding > bytes-used {
		return TableRefuseTruncated
	}
	used += padding
	if uintptr(base)%64 != 0 {
		return TableRefuseUnalignedBase
	}
	block.Base = base
	block.Projection = (*RawTokensBlockProjection)(base)
	block.Bytes = used
	return nil
}

// RawTokensCounts is gathered before Begin; clamping is the caller's policy.
type RawTokensCounts struct {
}

// RawTokensBlockStorage owns a maximum-sized extent. Do not copy an initialized storage.
type RawTokensBlockStorage struct {
	base       unsafe.Pointer
	allocation []byte
	allocator  TableBlockAllocator
}

func (s *RawTokensBlockStorage) Create(a TableBlockAllocator) bool {
	if s == nil || s.allocation != nil || a.Alloc == nil || a.Free == nil {
		return false
	}
	raw := a.Alloc(RawTokensBlockMaxBytes + 63)
	if int64(len(raw)) < RawTokensBlockMaxBytes+63 {
		if raw != nil {
			a.Free(raw)
		}
		return false
	}
	s.allocation = raw
	s.allocator = a
	offset := (-uintptr(unsafe.Pointer(&raw[0]))) & 63
	s.base = unsafe.Pointer(&raw[offset])
	return true
}
func (s *RawTokensBlockStorage) Destroy() {
	if s != nil && s.allocation != nil {
		s.allocator.Free(s.allocation)
		*s = RawTokensBlockStorage{}
	}
}

// ---- block fill path: begin ----
// RawTokensBlockBegin writes only the prologue and triples, never rows or padding.
// Storage and all counts are checked before any byte of the extent changes.
func RawTokensBlockBegin(b *RawTokensBlock, s *RawTokensBlockStorage, c RawTokensCounts, refusal *TableBlockRefusal) bool {
	if refusal != nil {
		*refusal = TableBlockRefusal{}
	}
	if b == nil {
		return false
	}
	if s == nil || s.base == nil {
		return false
	}
	p := (*RawTokensBlockProjection)(s.base)
	p.Magic = TableBlockMagic
	p.BuildVersion = BuildVersion
	p.ByteOrder = TableBlockByteOrder
	offset := int64(120)
	*b = RawTokensBlock{Base: s.base, Projection: p, Bytes: (offset + 63) &^ int64(63)}
	return true
}

func RawTokensBlockBytes(b *RawTokensBlock) int64 {
	if b == nil || b.Projection == nil {
		return 0
	}
	used := int64(120)
	return (used + 63) &^ int64(63)
}

// ---- block fill path: end ----

// Type is this block's descriptors: constant data, so a reflective read costs
// a lookup and not a parse. The row layouts hang off the element column
// rather than taking names of their own, so a walker reaches every record
// through the graph.
func (b *RawTokensBlock) Type() *TableBlockInfo { return &tableBlockRecords[0] }

